package ru.warriorrus.app.settings;

import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;
import ru.warriorrus.app.ReferenceMenu;

/** Preference-list screen: each row opens its own chooser and applies immediately. */
public final class SettingsScreen {
  private final Activity activity;private final SharedPreferences prefs;private final Runnable changed;
  private final ReferenceMenu ui;private final LinearLayout root,body;private final ScrollView scroll;
  public SettingsScreen(Activity activity,Runnable close,Runnable changed){this.activity=activity;this.changed=changed;prefs=activity.getPreferences(0);ui=new ReferenceMenu(activity);root=new LinearLayout(activity);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xffd6ecff);
    LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);header.setBackgroundColor(0xffb2d5f2);TextView title=new TextView(activity);title.setText("Настройки");title.setTextColor(ReferenceMenu.TEXT);title.setTextSize(19);title.setPadding(ui.dp(12),0,0,0);header.addView(title,new LinearLayout.LayoutParams(0,ui.dp(52),1));Button dismiss=ui.action("×",close);dismiss.setContentDescription("Закрыть настройки");header.addView(dismiss,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(52)));root.addView(header);
    scroll=new ScrollView(activity);body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));render();
  }
  public View view(){return root;}
  private void section(String title){ui.heading(body,title,"",null);}
  private LinearLayout labels(String title,String subtitle){LinearLayout column=new LinearLayout(activity);column.setOrientation(LinearLayout.VERTICAL);column.setPadding(ui.dp(12),ui.dp(8),ui.dp(10),ui.dp(8));TextView name=new TextView(activity);name.setText(title);name.setTextSize(17);name.setTextColor(ReferenceMenu.TEXT);column.addView(name);if(!subtitle.isEmpty()){TextView value=new TextView(activity);value.setText(subtitle);value.setTextSize(12);value.setTextColor(ReferenceMenu.MUTED);column.addView(value);}return column;}
  private void row(String title,String subtitle,Runnable action){LinearLayout row=labels(title,subtitle);row.setTag("setting:"+title);row.setContentDescription(title);row.setMinimumHeight(ui.dp(52));row.setOnClickListener(v->action.run());body.addView(row,new LinearLayout.LayoutParams(-1,-2));}
  private void toggle(String key,String title,String subtitle,boolean fallback){LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(labels(title,subtitle),new LinearLayout.LayoutParams(0,-2,1));CheckBox box=new CheckBox(activity);box.setContentDescription(title);box.setChecked(prefs.getBoolean(key,fallback));box.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean(key,on).apply();changed.run();});row.addView(box,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));row.setOnClickListener(v->box.setChecked(!box.isChecked()));body.addView(row);}
  private void refresh(){int y=scroll.getScrollY();body.removeAllViews();render();scroll.post(()->scroll.scrollTo(0,y));}
  private void choice(String key,String title,String[] values,int fallback){int selected=Math.max(0,Math.min(values.length-1,prefs.getInt(key,fallback)));row(title,values[selected],()->new AlertDialog.Builder(activity).setTitle(title).setSingleChoiceItems(values,selected,(d,n)->{prefs.edit().putInt(key,n).apply();changed.run();refresh();d.dismiss();}).setNegativeButton("Отмена",null).show());}
  private void range(String key,String title,int min,int max,int fallback){row(title,String.valueOf(prefs.getInt(key,fallback)),()->{LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);TextView value=new TextView(activity);SeekBar bar=new SeekBar(activity);bar.setMax(max-min);bar.setProgress(Math.max(0,Math.min(max-min,prefs.getInt(key,fallback)-min)));value.setText(String.valueOf(bar.getProgress()+min));form.addView(value);form.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){value.setText(String.valueOf(p+min));}});new AlertDialog.Builder(activity).setTitle(title).setView(form).setPositiveButton("ОК",(d,w)->{prefs.edit().putInt(key,bar.getProgress()+min).apply();changed.run();refresh();}).setNegativeButton("Отмена",null).show();});}
  private void coordinates(boolean secondary){String key=secondary?"secondaryCoordinates":"primaryCoordinates",title=secondary?"Доп. формат местоположения":"Формат местоположения";int mode=prefs.getInt(key,secondary?4:0);String summary=mode<0?"Не показывать":Coordinates.NAMES[Math.max(0,Math.min(Coordinates.NAMES.length-1,mode))];row(title,summary,()->{String[] names=new String[Coordinates.NAMES.length+(secondary?1:0)];if(secondary)names[0]="Не показывать";System.arraycopy(Coordinates.NAMES,0,names,secondary?1:0,Coordinates.NAMES.length);new AlertDialog.Builder(activity).setTitle(title).setSingleChoiceItems(names,Math.max(0,mode+(secondary?1:0)),(d,n)->{int selected=n-(secondary?1:0);d.dismiss();if(selected==10){EditText input=new EditText(activity);String codeKey=secondary?"secondaryEPSG":"primaryEPSG";input.setText(prefs.getString(codeKey,"EPSG:32637"));AlertDialog code=new AlertDialog.Builder(activity).setTitle("Код EPSG").setView(input).setPositiveButton("ОК",null).setNegativeButton("Отмена",null).create();code.setOnShowListener(v->code.getButton(-1).setOnClickListener(w->{try{ProjectionMath.name(input.getText().toString());prefs.edit().putString(codeKey,ProjectionMath.code(input.getText().toString())).putInt(key,selected).apply();changed.run();refresh();code.dismiss();}catch(Exception error){input.setError(error.getMessage());}}));code.show();}else{prefs.edit().putInt(key,selected).apply();changed.run();refresh();}}).setNegativeButton("Отмена",null).show();});}
  private void cacheLocation(){List<File> locations=new ArrayList<>();locations.add(new File(activity.getFilesDir(),"map-cache"));File[] external=activity.getExternalFilesDirs(null);if(external!=null)for(File f:external)if(f!=null)locations.add(new File(f,"map-cache"));String[] names=new String[locations.size()];for(int n=0;n<names.length;n++)names[n]=locations.get(n).getAbsolutePath();new AlertDialog.Builder(activity).setTitle("Путь к кэшу карт").setItems(names,(d,n)->{File file=locations.get(n);if(!file.isDirectory()&&!file.mkdirs()){new AlertDialog.Builder(activity).setMessage("Каталог недоступен для записи").setPositiveButton("ОК",null).show();return;}prefs.edit().putString("tileCachePath",file.getAbsolutePath()).apply();refresh();new AlertDialog.Builder(activity).setMessage("Новый каталог будет использоваться после перезапуска приложения. Данные прежнего кэша остаются в прежнем каталоге.").setPositiveButton("ОК",null).show();}).setNegativeButton("Отмена",null).show();}
  private void render(){section("Единицы");coordinates(false);coordinates(true);choice("distanceUnits","Формат расстояния",DisplayUnits.DISTANCE,0);choice("areaUnits","Формат площади",DisplayUnits.AREA,0);choice("angleUnits","Азимут",DisplayUnits.ANGLE,0);choice("slopeUnits","Уклон",DisplayUnits.SLOPE,1);choice("pressureUnits","Давление",DisplayUnits.PRESSURE,0);choice("northReference","Направление на север",new String[]{"Истинный (географический) север","Координатный север","Магнитный север"},2);
    section("Общее");row("Путь к кэшу карт","Выбрать место сохранения загруженных карт.",this::cacheLocation);toggle("hideStatusBar","Скрыть строку состояния","Для временного отображения строки состояния коснитесь кнопки главного меню.",false);toggle("immersive","Режим погружения","Скрыть кнопки панели навигации устройства в режиме просмотра карты.",false);toggle("showWhenLocked","На заблокированном экране","Для доступа к приложению разблокировка экрана не требуется.",false);toggle("keepScreenOn","Экран всегда включён","Не отключать экран в режиме просмотра карты.",false);toggle("confirmExit","Подтверждать выход","Запросить подтверждение перед выходом.",false);
    section("Экран");row("Управление масштабом","Выбрать инструменты управления масштабом карты.",()->zoomSettings());choice("longPressMap","Долгое нажатие на карту",new String[]{"Меню карты","Создать метку","Копировать координаты","Нет действия"},0);toggle("pinchZoom","Масштабирование жестом","Масштабировать карту пальцами.",true);toggle("manualRotation","Поворот карты жестом","Изменить ориентацию вращением карты пальцами.",true);
    section("Метки");range("markerSize","Размер меток",8,56,24);range("lineWidth","Толщина линий",1,12,3);
  }
  private void zoomSettings(){LinearLayout form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);for(String key:new String[]{"zoomButtons","volumeZoom"}){CheckBox box=new CheckBox(activity);box.setText(key.equals("zoomButtons")?"Кнопки масштаба":"Масштабировать клавишами громкости");box.setChecked(prefs.getBoolean(key,true));box.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean(key,on).apply();changed.run();});form.addView(box);}new AlertDialog.Builder(activity).setTitle("Управление масштабом").setView(form).setPositiveButton("ОК",null).show();}
}
